def checkSubarraySum(nums: list[int], k: int) -> bool:
    rem_map = {0: -1}
    curr = 0
    for i, n in enumerate(nums):
        curr = (curr + n) % k
        if curr in rem_map:
            if i - rem_map[curr] >= 2:
                return True
        else:
            rem_map[curr] = i
    return False

